/// 🧾 Overlays layout + metadata from `@semio-tech/compose-js` `KitFullDto`-style JSON (`types`, `designs`, `pieces`); control plane authoritative copy stays in-process.
pub async fn hydrate_from_kit_full_snapshot_json(self: &Arc<Self>, dto: &serde_json::Value) -> Result<(), crate::error::ComposeError> {
    if let Some(n) = dto.get("name").and_then(|v| v.as_str()) {
        *self.name.write().await = n.to_string();
    }
    let Some(id_override) = dto.get("id").and_then(|v| v.as_str()) else {
        return Ok(());
    };
    *crate::kit::_kit_id_cell(self)? = crate::id::Id::from(id_override);

    {
        let mut tys = self.types.write().await;
        tys.clear();
        let Some(types_arr) = dto.get("types").and_then(|v| v.as_array()) else { return Ok(()); };
        let owner = Arc::downgrade(self);
        for t in types_arr {
            let Some(ts) = t.get("id").and_then(|x| x.as_str()) else { continue };
            let nm = t.get("name").and_then(|x| x.as_str()).unwrap_or("");
            let row = crate::kit::r#type::Type::new_with_external_id(owner.clone(), ts.into(), nm.to_string()).await;
            tys.push(row);
        }
    }
    {
        let mut designs = self.designs.write().await;
        designs.clear();
        self.design_id_to_index.write().await.clear();
        let owner = Arc::downgrade(self);
        let empty: &[serde_json::Value] = &[];
        let design_arr = dto.get("designs").and_then(|v| v.as_array()).unwrap_or(&empty[..]);
        for d in design_arr {
            let Some(ds) = d.get("id").and_then(|x| x.as_str()) else { continue };
            let dn = d.get("name").and_then(|x| x.as_str()).unwrap_or(ds);
            let des = crate::kit::design::Design::with_id(owner.clone(), ds.into(), dn.to_string()).await;
            crate::kit::design::hydrate_design_pieces_from_json(&des, self, d).await?;
            let mut dz = self.designs.write().await;
            let mut ix = self.design_id_to_index.write().await;
            let slot = dz.len();
            dz.push(des);
            ix.insert(ds.into(), slot);
        }
    }
    Ok(())
}

/// 🧾 Canonical JSON snapshot consumed by `@semio-tech/compose-js` `fullSnapshot` (no duplicated layout client-side).
pub async fn kit_full_snapshot_value(&self) -> serde_json::Value {
    let id = crate::kit::_kit_id_read(self).await;
    let name = self.name.read().await.clone();

    let types = {
        let tys = self.types.read().await;
        let mut out = Vec::<serde_json::Value>::with_capacity(tys.len());
        for t in tys.iter() {
            let tid = t.id.clone();
            let nm = t.name.read().await.clone();
            out.push(serde_json::json!({"id": tid.as_str(), "name": nm, "connectors": []}));
        }
        serde_json::Value::Array(out)
    };

    let mut designs_arr = Vec::<serde_json::Value>::new();
    {
        let dz = self.designs.read().await;
        for d in dz.iter() {
            let mut pieces_arr = Vec::<serde_json::Value>::new();
            let plist = d.pieces.read().await;
            for p in plist.iter() {
                let pos = (*p.position.read().await).unwrap_or_default();
                let tid = match p.blueprint.read().await.clone() {
                    crate::kit::r#type::Blueprint::Type(ty) => ty.id.clone(),
                    crate::kit::r#type::Blueprint::Design(_) => continue,
                };
                let pname = (*p.name.read().await).clone().unwrap_or_default();
                pieces_arr.push(serde_json::json!({
                  "id": p.id.as_str(),
                  "name": pname,
                  "type": { "id": tid.as_str(), "hash": ty.hash },
                  "plane": serde_json::to_value(pos.plane).unwrap_or_default(),
                  "center": serde_json::to_value(pos.center).unwrap_or_default(),
                  "scale": p.scale.read().await.unwrap_or(1.0),
                  "color": "#000000",
                  "props": [],
                  "attributes": [],
                }));
            }
            designs_arr.push(serde_json::json!({
               "id": d.id.as_str(),
               "name": d.name.read().await.clone(),
               "pieces": pieces_arr,
               "connections": [],
            }));
        }
    }

    serde_json::json!({
        "id": id.as_str(),
        "name": name,
        "createdAt": "2020-01-01T00:00:00.000Z",
        "updatedAt": "2020-01-01T00:00:00.000Z",
        "types": types,
        "designs": designs_arr,
        "authors": [],
        "concepts": [],
        "qualities": [],
        "tags": [],
        "props": [],
        "folders": [],
        "files": [],
        "layers": [],
        "stats": [],
        "groups": [],
    })
}

