async readDesignFlattenMap(scope: KitReadScope, designId: string): Promise<readonly DesignFlattenMapEntryDto[]> {
  const data = await this.gqlRunSessionWipStore(scope, `design(id: $id) { flattenMap }`, { id: designId });
  const raw = (gqlDataSessionWipKitStore(data, scope)?.["design"] as JsonObject | undefined)?.["flattenMap"];
  const FlatRow = z.object({ pieceId: z.string(), plane: PlaneSchema, center: PointSchema });
  if (Array.isArray(raw)) {
    const out: DesignFlattenMapEntryDto[] = [];
    for (const row of raw) {
      const pr = FlatRow.safeParse(row);
      if (pr.success) out.push(pr.data);
    }
    return out;
  }
  if (typeof raw === "string") {
    try {
      const p = parseJsonValue(raw) as JsonValue;
      if (!Array.isArray(p)) return [];
      const out: DesignFlattenMapEntryDto[] = [];
      for (const row of p) {
        const pr = FlatRow.safeParse(row);
        if (pr.success) out.push(pr.data);
      }
      return out;
    } catch {
      return [];
    }
  }
  return [];
}

async read(scope: KitReadScope, batch: ReadBatch): Promise<ReadBatchResult> {
  this.ensureAlive();
  const out: ReadKitCommandOutput[] = [];
  for (const c of batch) out.push(await this.mapReadCommand(scope, c));
  return out;
}

/** @emoji 🧾 Apply typed `ChangeKitCommand` batch inside the active session draft transaction (`kitStore.batch`). */
async submitChangeKitCommands(commands: readonly ChangeKitCommand[]): Promise<SetResult> {
  try {
    const rows = await this.runScopedTransactionBatch([{ changeKitCommands: { commands: [...commands] } } as JsonObject]);
    for (const row of rows) {
      if (row.ok === false) return { ok: false, error: { kind: "Internal", message: `batch ${String(row.kind)}` } };
    }
    return { ok: true };
  } catch (e) {
    return { ok: false, error: { kind: "Internal", message: String(e) } };
  }
}

private async mapReadCommand(scope: KitReadScope, c: ReadKitCommand): Promise<ReadKitCommandOutput> {
  if ("readKitFullCommand" in c && c.readKitFullCommand === null) {
    const d = await this.materializedLiveJsonForReadScope(scope);
    return { readKitFullCommand: { full: d } };
  }
  if ("readKitShallowCommand" in c && c.readKitShallowCommand === null) {
    const row = await this.gqlKitReadOnlyScope(scope, `shallow { types { ${KIT_GQL_TYPE_SHALLOW_FIELDS} } designs { ${KIT_GQL_DESIGN_SHALLOW_FIELDS} } }`);
    const shallowRoot = kitGraphqlKitShallowRoot(row);
    return {
      readKitShallowCommand: {
        types: composeParseTypeShallowArrayJson(kitGraphqlShallowPacketsFromArray(shallowRoot.types) as unknown as KitJsonTreeDto[]),
        designs: composeParseDesignShallowArrayJson(kitGraphqlShallowPacketsFromArray(shallowRoot.designs) as unknown as KitJsonTreeDto[]),
      },
    };
  }
  if ("readKitTypeIdsCommand" in c && c.readKitTypeIdsCommand === null) {
    const row = await this.gqlKitReadOnlyScope(scope, "types { id }");
    return { readKitTypeIdsCommand: { typeIds: composeParseKitIdDtoArray(row.types as KitJsonTreeDto | string) } };
  }
  if ("readKitDesignIdsCommand" in c && c.readKitDesignIdsCommand === null) {
    const row = await this.gqlKitReadOnlyScope(scope, "designs { id }");
    return { readKitDesignIdsCommand: { designIds: composeParseKitIdDtoArray(row.designs as KitJsonTreeDto | string) } };
  }
  if ("readKitTypesMetadataCommand" in c && c.readKitTypesMetadataCommand === null) {
    const row = await this.gqlKitReadOnlyScope(scope, `types { metadata { ${KIT_GQL_TYPE_METADATA_FIELDS} } }`);
    const metas = kitGraphqlExtractNestedMetadata(row.types as JsonValue);
    return { readKitTypesMetadataCommand: { types: composeParseTypeMetadataArrayJson(metas as unknown as KitJsonTreeDto[]) } };
  }
  if ("readKitDesignsMetadataCommand" in c && c.readKitDesignsMetadataCommand === null) {
    const row = await this.gqlKitReadOnlyScope(scope, `designs { metadata { ${KIT_GQL_DESIGN_METADATA_FIELDS} } }`);
    const metas = kitGraphqlExtractNestedMetadata(row.designs as JsonValue);
    return { readKitDesignsMetadataCommand: { designs: composeParseDesignMetadataArrayJson(metas as unknown as KitJsonTreeDto[]) } };
  }
  if ("readKitTypesShallowCommand" in c && c.readKitTypesShallowCommand === null) {
    const row = await this.gqlKitReadOnlyScope(scope, `types { shallow { ${KIT_GQL_TYPE_SHALLOW_FIELDS} } }`);
    return {
      readKitTypesShallowCommand: {
        types: composeParseTypeShallowArrayJson(kitGraphqlShallowPacketsFromArray(row.types as JsonValue) as unknown as KitJsonTreeDto[]),
      },
    };
  }
  if ("readKitDesignsShallowCommand" in c && c.readKitDesignsShallowCommand === null) {
    const row = await this.gqlKitReadOnlyScope(scope, `designs { shallow { ${KIT_GQL_DESIGN_SHALLOW_FIELDS} } }`);
    return {
      readKitDesignsShallowCommand: {
        designs: composeParseDesignShallowArrayJson(kitGraphqlShallowPacketsFromArray(row.designs as JsonValue) as unknown as KitJsonTreeDto[]),
      },
    };
  }
  if ("readKitAuthorsShallowCommand" in c && c.readKitAuthorsShallowCommand === null) {
    const row = await this.gqlKitReadOnlyScope(scope, "shallow { authors { id name email role rank } }");
    const shallowRoot = kitGraphqlKitShallowRoot(row);
    return {
      readKitAuthorsShallowCommand: {
        authors: composeParseAuthorMetadataArrayJson((shallowRoot.authors as KitJsonTreeDto) ?? []),
      },
    };
  }
  if ("readKitMetadataCommand" in c && c.readKitMetadataCommand === null) {
    const row = await this.gqlKitReadOnlyScope(scope, "metadata { id name description icon image preview remote homepage license uri created updated version }");
    return { readKitMetadataCommand: { metadata: composeParseKitMetadataJson(row.metadata as KitJsonTreeDto) } };
  }
  if ("readKitDesignCommands" in c && c.readKitDesignCommands) {
    const { id, commands } = c.readKitDesignCommands;
    const results: ReadDesignCommandOutput[] = [];
    for (const sub of commands) results.push(await this.mapDesignRead(scope, id.id, sub));
    return { readKitDesignCommands: { results } };
  }
  if ("readKitTypeCommands" in c && c.readKitTypeCommands) {
    const { id, commands } = c.readKitTypeCommands;
    const results: ReadTypeCommandOutput[] = [];
    for (const sub of commands) results.push(await this.mapTypeRead(scope, id.id, sub));
    return { readKitTypeCommands: { results } };
  }
  throw new Error(`read: unsupported ${Object.keys(c).join(",")}`);
}

